import{_ as t,o as a,c as r,a2 as s}from"./chunks/framework.BZO4qERu.js";const u=JSON.parse('{"title":"Results and history","description":"","frontmatter":{},"headers":[],"relativePath":"guide/results.md","filePath":"guide/results.md","lastUpdated":1792570296000}'),o={name:"guide/results.md"};function n(i,e,d,l,h,p){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="results-and-history" tabindex="-1">Results and history <a class="header-anchor" href="#results-and-history" aria-label="Permalink to &quot;Results and history&quot;">​</a></h1><p>Inspect your reading list, select what matters, and export it into your own research workflow.</p><h2 id="three-independent-histories" tabindex="-1">Three independent histories <a class="header-anchor" href="#three-independent-histories" aria-label="Permalink to &quot;Three independent histories&quot;">​</a></h2><p>Search runs, analyses, and reviews are saved separately — each module in the sidebar shows its own history. Where history lives, how records are renamed, exported, or deleted, and what survives a reload: <a href="./workspace">Workspace and history</a>.</p><h2 id="read-a-paper-card" tabindex="-1">Read a paper card <a class="header-anchor" href="#read-a-paper-card" aria-label="Permalink to &quot;Read a paper card&quot;">​</a></h2><p>Results can include titles, authors, years, venues, abstracts, source links, identifiers, citation information, and relevance explanations. Availability depends on the source.</p><p>Relevance measures the match to <strong>your question</strong>. It is not a study-quality score or permission to cite a paper without reading it.</p><h2 id="filter-sort-and-select" tabindex="-1">Filter, sort, and select <a class="header-anchor" href="#filter-sort-and-select" aria-label="Permalink to &quot;Filter, sort, and select&quot;">​</a></h2><p>Result controls search the returned set, apply available filters, and change the order. They do not issue a fresh external search.</p><p>Select individual papers for a smaller export or a review, and check the selected count before continuing. <strong>Select loaded</strong> applies only to the currently loaded papers. Review creation requires 2–256 selected papers. Switching modules preserves the selection during this session.</p><h2 id="export" tabindex="-1">Export <a class="header-anchor" href="#export" aria-label="Permalink to &quot;Export&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Format</th><th>Use</th></tr></thead><tbody><tr><td>CSV</td><td>Spreadsheets and manual screening</td></tr><tr><td>JSON</td><td>Structured downstream processing</td></tr><tr><td>Selected CSV / JSON</td><td>Only the selected papers</td></tr></tbody></table><p>The <strong>Export</strong> menu groups complete and selected CSV/JSON downloads. A complete export covers the stored results, not just the visible page. Original-record links take you to the source; PaperSeek does not bulk-download paywalled text.</p><p><a href="./reviews">Review exports</a> use Markdown, Word, and BibTeX.</p><h2 id="reopen-history" tabindex="-1">Reopen history <a class="header-anchor" href="#reopen-history" aria-label="Permalink to &quot;Reopen history&quot;">​</a></h2><p>Community history belongs to the local database. Online history belongs to your account. <a href="./../online/privacy#search-without-signing-in">Signing in after an anonymous search</a> does not backfill it.</p><p>A saved run retains its actual settings. Reopening it does not replace its model or budget with current defaults; older unrecorded fields remain unknown.</p><p>You can delete finished history items after exporting anything you need. Active tasks must end first.</p><h2 id="start-a-review" tabindex="-1">Start a review <a class="header-anchor" href="#start-a-review" aria-label="Permalink to &quot;Start a review&quot;">​</a></h2><p>Select at least two papers with useful abstracts, or create a review through <strong>Reviews</strong>. Follow the <a href="./reviews">outline and writing guide</a>.</p>',20)])])}const y=t(o,[["render",n]]);export{u as __pageData,y as default};
